ee:variables.ee:set-variable:
%dw 2.0
import * from dw::Runtime
output application/json
var processCode = vars.processCode match {
	case "SALE" -> "postSale"
	case "SERVICE_ADDITION" -> "postServiceAddition"
	else -> fail("Invalid Process Code")
}
var requestHeaders = attributes.headers
---
{
	host: p('zsmart-sapi.host'),
	port: p('zsmart-sapi.port'),
	basepath: p('zsmart-sapi.base-path'),
	path: p('zsmart-sapi.' ++ processCode ++ ".path"),
	method: p('zsmart-sapi.' ++ processCode ++ ".method"),
	headers: {
		"client_secret": p('zsmart-sapi.security.client_secret'),
		"client_id": p('zsmart-sapi.security.client_id'),
		"name": requestHeaders.name,
		"X-CORRELATION-ID": requestHeaders."X-CORRELATION-ID",
		"source": requestHeaders.source,
		"systemId": requestHeaders.systemId
	},
	queryParameters: {
	},
	uriParameters: {
	},
	responseTimeout: p('configurationTimeout.zsmart-sapi.responseTimeout')
}

%dw 2.0
import * from dw::Runtime
output application/java
---
(vars.processCode) match {
	case "SALE" -> readUrl('classpath://dwScripts/postBillingProcess/saleMapping.dwl', 'text/plain')
	case "SERVICE_ADDITION" -> readUrl('classpath://dwScripts/postBillingProcess/serviceAddMapping.dwl', 'text/plain')
	else -> fail("Invalid Process Code")
}
